import {isDemo,call} from '../service'
const key='sisu-wallet-preview-v1'
const seed=()=>({wallets:[{name:'W-NIMAL',owner_user:'TC-SLDA-0001',beneficiary:'Teacher',country:'Sri Lanka',currency:'LKR',available_minor:4250000,held_minor:0},{name:'W-INTL',owner_user:'TC-SLDA-0002',beneficiary:'Teacher',country:'United Arab Emirates',currency:'USD',available_minor:24000,held_minor:0},{name:'W-INSTITUTE',owner_user:'ADMIN',beneficiary:'Institute',country:'Sri Lanka',currency:'LKR',available_minor:18500000,held_minor:0}],methods:[],requests:[],ledger:[]})
function read(){try{return JSON.parse(localStorage.getItem(key))||seed()}catch{return seed()}}
function save(d){localStorage.setItem(key,JSON.stringify(d))}
export async function walletCall(method,args,member){
 if(!isDemo)return call(method,args,'wallet')
 const d=read(),admin=member.role==='PlatformAdmin',id=member.role==='Admin'?'ADMIN':member.name
 let own=d.wallets.filter(w=>w.owner_user===id)
 if(!own.length&&!admin){const w={name:'W-'+id,owner_user:id,beneficiary:member.role==='Admin'?'Institute':'Teacher',country:'Sri Lanka',currency:'LKR',available_minor:1500000,held_minor:0};d.wallets.push(w);own=[w];save(d)}
 const w=d.wallets.find(w=>w.name===args?.wallet)||own[0]
 const requireAdmin=()=>{if(!admin)throw Error('Platform owner access required')}
 const requireOwn=()=>{if(!w||w.owner_user!==id)throw Error('Wallet unavailable')}
 const ledger=(kind,da,dh,ref)=>{w.available_minor+=da;w.held_minor+=dh;d.ledger.unshift({name:crypto.randomUUID(),wallet:w.name,kind,available_delta:da,held_delta:dh,available_after:w.available_minor,reference:ref,creation:new Date().toISOString()})}
 if(method==='dashboard'){requireOwn();return {wallets:own,wallet:w,minimum_minor:w.currency==='LKR'?600000:2000,ledger:d.ledger.filter(l=>l.wallet===w.name),methods:d.methods.filter(m=>m.wallet===w.name),requests:d.requests.filter(r=>r.wallet===w.name)}}
 if(method==='submit_method'){requireOwn();const fields=args.data;const m={name:crypto.randomUUID(),wallet:w.name,kind:fields.kind,country:w.country,masked_label:fields.kind+' · demo ••••0000',status:'Pending',details:{...fields},creation:new Date().toISOString()};d.methods.unshift(m);save(d);return {name:m.name}}
 if(method==='review_method'){requireAdmin();const m=d.methods.find(m=>m.name===args.method);if(!m||m.status!=='Pending')throw Error('Method already reviewed');if(!args.reason?.trim())throw Error('Add a review reason');if(args.decision==='Approved')d.methods.filter(x=>x.wallet===m.wallet&&x.status==='Approved').forEach(x=>x.status='Superseded');m.status=args.decision;m.review_reason=args.reason;save(d);return {status:m.status}}
 if(method==='reveal_method'){requireAdmin();return d.methods.find(m=>m.name===args.method)?.details}
 if(method==='request_payout'){requireOwn();const existing=d.requests.find(r=>r.request_key===args.request_key&&r.wallet===w.name);if(existing)return existing;const amount=Math.round(Number(args.amount)*100),m=d.methods.find(m=>m.name===args.method&&m.wallet===w.name&&m.status==='Approved');if(!m)throw Error('Add a method and wait for approval');if(!Number.isFinite(amount)||amount<(w.currency==='LKR'?600000:2000)||amount>w.available_minor)throw Error('Minimum payout not met or insufficient funds');const req={name:'PO-'+crypto.randomUUID().slice(0,8),wallet:w.name,method:m.name,request_key:args.request_key,amount_minor:amount,currency:w.currency,region:w.country==='Sri Lanka'?'Local':'International',status:'Pending',creation:new Date().toISOString()};d.requests.unshift(req);ledger('Reserve',-amount,amount,req.name);save(d);return req}
 if(method==='admin_queue'){requireAdmin();return {requests:d.requests.filter(r=>r.region===args.region&&['Pending','Processing'].includes(r.status)),methods:d.methods.filter(m=>m.status==='Pending'&&(args.region==='Local'?m.country==='Sri Lanka':m.country!=='Sri Lanka'))}}
 if(method==='update_payout'){requireAdmin();const req=d.requests.find(r=>r.name===args.request);if(!req)throw Error('Unknown payout');if(!({Pending:['Processing','Rejected'],Processing:['Completed','Rejected']}[req.status]||[]).includes(args.status))throw Error('Invalid transition');if(args.status==='Completed'&&!args.reference?.trim())throw Error('Transfer reference required');if(args.status==='Rejected'&&!args.reason?.trim())throw Error('Rejection reason required');const wallet=d.wallets.find(x=>x.name===req.wallet);if(args.status!=='Processing'){wallet.held_minor-=req.amount_minor;if(args.status==='Rejected')wallet.available_minor+=req.amount_minor;d.ledger.unshift({name:crypto.randomUUID(),wallet:wallet.name,creation:new Date().toISOString(),kind:args.status==='Rejected'?'Release':'Payout',available_delta:args.status==='Rejected'?req.amount_minor:0,held_delta:-req.amount_minor,available_after:wallet.available_minor,reference:req.name})}req.status=args.status;req.transaction_reference=args.reference;req.reason=args.reason;save(d);return req}
 throw Error('Wallet action unavailable')
}
export function localExport(rows){return '\ufeffPayout reference,Wallet,Amount,Currency,Status\r\n'+rows.map(r=>[r.name,r.wallet,(r.amount_minor/100).toFixed(2),r.currency,r.status].map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n')}
